/**
 * QR code as an inline SVG (library `uqr`, no other dependency). The SVG is built here from
 * the module matrix: one path, `currentColor` for the dark modules, transparent background, a
 * quiet zone of `margin` modules.
 *
 * Safe to inject with `{@html}` only because the SVG contains nothing but numbers produced
 * here: the encoded text never appears in it. The text itself must be an URL generated by the
 * server (pairing URL), never user content.
 */
import { encode } from 'uqr';

export interface QrOptions {
  /** Quiet zone in modules (4 by the QR specification). */
  readonly margin?: number;
  readonly ecc?: 'L' | 'M' | 'Q' | 'H';
}

export function qrSvg(text: string, options: QrOptions = {}): string {
  const margin = Math.max(0, Math.floor(options.margin ?? 4));
  const { data, size } = encode(text, { ecc: options.ecc ?? 'M', border: 0 });
  const total = size + 2 * margin;
  let path = '';
  for (let y = 0; y < size; y++) {
    const row = data[y] ?? [];
    for (let x = 0; x < size; x++) {
      if (row[x] !== true) continue;
      let end = x + 1;
      while (end < size && row[end] === true) end++;
      path += `M${x + margin} ${y + margin}h${end - x}v1h-${end - x}z`;
      x = end;
    }
  }
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${total} ${total}" ` +
    `shape-rendering="crispEdges" role="img" data-modules="${size}">` +
    `<path fill="currentColor" d="${path}"/></svg>`
  );
}
